#!/usr/bin/env node
// Stable entry point committed to the repo (dist/ is generated by `npm run build`).
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const bundle = fileURLToPath(new URL('../dist/agentdash.mjs', import.meta.url));
if (!existsSync(bundle)) {
  process.stderr.write('agentdash: falta compilar. Ejecuta "npm install && npm run build" en la carpeta del repo.\n');
  process.exit(1);
}
await import(bundle);
